from AlgorithmImports import *


class IndependentSlotsAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            security = self.AddEquity(
                ticker,
                Resolution.Daily,
                Market.USA,
                False
            )
            self.symbols[ticker] = security.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            14,
            MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot_shares = 0
        self.aapl_lot_shares = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

        self.SetWarmUp(self.SMA_PERIOD + 1, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars
        has_spy = bars.ContainsKey(self.spy)
        has_aapl = bars.ContainsKey(self.aapl)

        spy_close = None
        current_spy_sma = None
        spy_crosses_above = False
        spy_crosses_below = False

        if has_spy:
            spy_bar = bars[self.spy]
            spy_close = float(spy_bar.Close)
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                ):
                    spy_crosses_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > current_spy_sma
                    )
                    spy_crosses_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < current_spy_sma
                    )

                self.previous_spy_sma = current_spy_sma
            else:
                self.previous_spy_sma = None

            self.previous_spy_close = spy_close

        aapl_close = None

        if has_aapl:
            aapl_bar = bars[self.aapl]
            aapl_close = float(aapl_bar.Close)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if (
                self.previous_aapl_close is not None
                and aapl_close < self.previous_aapl_close
            ):
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        all_bars_present = all(
            bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if self.IsWarmingUp or not all_bars_present:
            return

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or current_spy_sma is None
        ):
            return

        if (
            self.spy_lot_shares > 0
            and not self.spy_order_pending
            and spy_crosses_below
        ):
            self._submit_spy_order(
                -self.spy_lot_shares,
                "STRATEGY_A_SELL"
            )

        if (
            self.aapl_lot_shares > 0
            and not self.aapl_order_pending
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self._submit_aapl_order(
                -self.aapl_lot_shares,
                "STRATEGY_B_SELL"
            )

        if (
            self.spy_lot_shares == 0
            and not self.spy_order_pending
            and spy_crosses_above
        ):
            target_value = 0.40 * float(
                self.Portfolio.TotalPortfolioValue
            )
            quantity = int(target_value / spy_close)

            if quantity > 0:
                self._submit_spy_order(
                    quantity,
                    "STRATEGY_A_BUY"
                )

        if (
            self.aapl_lot_shares == 0
            and not self.aapl_order_pending
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000
        ):
            quantity = int(20_000 / aapl_close)

            if quantity > 0:
                self._submit_aapl_order(
                    quantity,
                    "STRATEGY_B_BUY"
                )

    def _submit_spy_order(self, quantity, tag):
        ticket = self.MarketOrder(self.spy, quantity, False, tag)
        self.spy_order_pending = self._is_ticket_pending(ticket)

    def _submit_aapl_order(self, quantity, tag):
        ticket = self.MarketOrder(self.aapl, quantity, False, tag)
        self.aapl_order_pending = self._is_ticket_pending(ticket)

    def _is_ticket_pending(self, ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        tag = order.Tag or ""

        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            fill_quantity = int(order_event.FillQuantity)

            if tag.startswith("STRATEGY_A_"):
                self.spy_lot_shares = max(
                    0,
                    self.spy_lot_shares + fill_quantity
                )
            elif tag.startswith("STRATEGY_B_"):
                self.aapl_lot_shares = max(
                    0,
                    self.aapl_lot_shares + fill_quantity
                )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if tag.startswith("STRATEGY_A_"):
                self.spy_order_pending = False
            elif tag.startswith("STRATEGY_B_"):
                self.aapl_order_pending = False

