class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.Settings.DailyPreciseEndTime = True

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, Market.USA, False
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_ma_period = 20
        self.spy_ma = SimpleMovingAverage(self.spy_ma_period)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_ma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_close_samples = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(self.spy_ma_period + 1, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = data.Bars

        has_spy = bars.ContainsKey(self.spy)
        has_aapl = bars.ContainsKey(self.aapl)

        prior_spy_close = self.previous_spy_close
        prior_spy_ma = self.previous_spy_ma
        current_spy_ma = None
        current_aapl_rsi = None

        if has_spy:
            spy_bar = bars[self.spy]
            self.spy_ma.Update(spy_bar.EndTime, spy_bar.Close)

            if self.spy_ma.IsReady:
                current_spy_ma = self.spy_ma.Current.Value

            self.previous_spy_close = spy_bar.Close
            self.previous_spy_ma = current_spy_ma

        if has_aapl:
            aapl_bar = bars[self.aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.aapl_close_samples += 1

            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close

            if self.aapl_rsi.IsReady:
                current_aapl_rsi = self.aapl_rsi.Current.Value

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if self.IsWarmingUp:
            return

        if (
            not self.spy_ma.IsReady
            or not self.aapl_rsi.IsReady
            or prior_spy_close is None
            or prior_spy_ma is None
            or current_spy_ma is None
            or current_aapl_rsi is None
            or self.aapl_close_samples < 4
        ):
            return

        spy_bar = bars[self.spy]
        aapl_bar = bars[self.aapl]

        if self.strategy_a_shares > 0:
            if (
                prior_spy_close >= prior_spy_ma
                and spy_bar.Close < current_spy_ma
            ):
                ticket = self.MarketOrder(
                    self.spy, -self.strategy_a_shares
                )
                if ticket is not None and ticket.Status != OrderStatus.Invalid:
                    self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if current_aapl_rsi > 60:
                ticket = self.MarketOrder(
                    self.aapl, -self.strategy_b_shares
                )
                if ticket is not None and ticket.Status != OrderStatus.Invalid:
                    self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if (
                prior_spy_close <= prior_spy_ma
                and spy_bar.Close > current_spy_ma
            ):
                target_value = (
                    0.40 * float(self.Portfolio.TotalPortfolioValue)
                )
                quantity = int(target_value / float(spy_bar.Close))

                if quantity > 0:
                    ticket = self.MarketOrder(self.spy, quantity)
                    if (
                        ticket is not None
                        and ticket.Status != OrderStatus.Invalid
                    ):
                        self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0:
            if self.aapl_red_streak >= 3:
                available_cash = float(self.Portfolio.Cash)

                if available_cash >= 20_000:
                    quantity = int(20_000 / float(aapl_bar.Close))

                    if quantity > 0:
                        ticket = self.MarketOrder(self.aapl, quantity)
                        if (
                            ticket is not None
                            and ticket.Status != OrderStatus.Invalid
                        ):
                            self.strategy_b_shares = quantity

