        self.SetCash(1_000_000)

        self.spy = self.AddEquity(
            "SPY", Resolution.Daily, Market.USA, False
        ).Symbol
        self.aapl = self.AddEquity(
            "AAPL", Resolution.Daily, Market.USA, False
        ).Symbol
        self.ibm = self.AddEquity(
            "IBM", Resolution.Daily, Market.USA, False
        ).Symbol
        self.bac = self.AddEquity(
            "BAC", Resolution.Daily, Market.USA, False
        ).Symbol
        self.aig = self.AddEquity(
            "AIG", Resolution.Daily, Market.USA, False
        ).Symbol

        self.subscribed_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig,
        ]

        self.spy_moving_average = SimpleMovingAverage(
            self.SPY_MOVING_AVERAGE_PERIOD
        )
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_moving_average = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(
            self.SPY_MOVING_AVERAGE_PERIOD + 1,
            Resolution.Daily
        )

    def OnData(self, data):
        self._apply_splits(data)

        spy_crossed_above = False
        spy_crossed_below = False

        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            spy_close = float(spy_bar.Close)

            self.spy_moving_average.Update(
                spy_bar.EndTime, spy_bar.Close
            )

            if self.spy_moving_average.IsReady:
                current_average = float(
                    self.spy_moving_average.Current.Value
                )

                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_moving_average is not None
                ):
                    spy_crossed_above = (
                        self.previous_spy_close
                        <= self.previous_spy_moving_average
                        and spy_close > current_average
                    )
                    spy_crossed_below = (
                        self.previous_spy_close
                        >= self.previous_spy_moving_average
                        and spy_close < current_average
                    )

                self.previous_spy_close = spy_close
                self.previous_spy_moving_average = current_average

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            aapl_close = float(aapl_bar.Close)

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
