from decimal import Decimal


class StrategySystemAlgorithm(QCAlgorithm):
    SPY_MOVING_AVERAGE_PERIOD = 200

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.AddEquity(
                ticker,
                Resolution.Daily,
                Market.USA,
                False
            )
            self.symbols[ticker] = security.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]
        self.all_symbols = tuple(self.symbols.values())

        self.spy_moving_average = SimpleMovingAverage(
            self.SPY_MOVING_AVERAGE_PERIOD
        )
        self.aapl_rsi = RelativeStrengthIndex(
            14,
            MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_moving_average = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = Decimal(0)
        self.aapl_lot = Decimal(0)

        self.SetWarmUp(
            self.SPY_MOVING_AVERAGE_PERIOD + 1,
            Resolution.Daily
        )

    def OnData(self, data):
        bars = {}
        all_bars_present = True

        for symbol in self.all_symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]
            else:
                all_bars_present = False

        spy_crossed_above = False
        spy_crossed_below = False

        if self.spy in bars:
            spy_bar = bars[self.spy]
            self.spy_moving_average.Update(
                spy_bar.EndTime,
                spy_bar.Close
            )

            if (
                self.spy_moving_average.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_moving_average is not None
            ):
                current_average = self.spy_moving_average.Current.Value

                spy_crossed_above = (
                    self.previous_spy_close
                    <= self.previous_spy_moving_average
                    and spy_bar.Close > current_average
                )
                spy_crossed_below = (
                    self.previous_spy_close
                    >= self.previous_spy_moving_average
                    and spy_bar.Close < current_average
                )

            if self.spy_moving_average.IsReady:
                self.previous_spy_close = spy_bar.Close
                self.previous_spy_moving_average = (
                    self.spy_moving_average.Current.Value
                )

        if self.aapl in bars:
            aapl_bar = bars[self.aapl]

            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close
            self.aapl_rsi.Update(
                aapl_bar.EndTime,
                aapl_bar.Close
            )

        if self.IsWarmingUp or not all_bars_present:
            return

        if (
            not self.spy_moving_average.IsReady
            or not self.aapl_rsi.IsReady
            or self.previous_spy_close is None
            or self.previous_spy_moving_average is None
            or self.previous_aapl_close is None
        ):
            return

        self.spy_lot = self.Portfolio[self.spy].Quantity
        self.aapl_lot = self.Portfolio[self.aapl].Quantity

        if self.spy_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = Decimal(0)

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.Current.Value > Decimal("60")
        ):
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = Decimal(0)

        if self.spy_lot == 0 and spy_crossed_above:
            target_value = (
                self.Portfolio.TotalPortfolioValue
                * Decimal("0.40")
            )
            quantity = int(target_value / bars[self.spy].Close)

            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = Decimal(quantity)

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = Decimal("20000")

            if self.Portfolio.Cash >= cash_to_invest:
                quantity = int(
                    cash_to_invest / bars[self.aapl].Close
                )

                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = Decimal(quantity)

