        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.spy_crossed_above = False
        self.spy_crossed_below = False
        self.last_spy_update = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.last_aapl_update = None

        self.spy_lot_shares = 0
        self.aapl_lot_shares = 0

        self.last_evaluation_time = None

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        self._reconcile_lots()

        if data.Bars.ContainsKey(self.spy):
            self._update_spy_state(data.Bars[self.spy])

        if data.Bars.ContainsKey(self.aapl):
            self._update_aapl_state(data.Bars[self.aapl])

        if self.IsWarmingUp:
            return

        if not all(
            data.Bars.ContainsKey(symbol)
            for symbol in self.required_symbols
        ):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        if self.last_evaluation_time == spy_bar.EndTime:
            return

        self.last_evaluation_time = spy_bar.EndTime

        if (
            not self.spy_sma.IsReady
            or self.previous_spy_close is None
            or self.previous_spy_sma is None
            or not self.aapl_rsi.IsReady
            or self.previous_aapl_close is None
        ):
            return

        if self.spy_lot_shares > 0 and self.spy_crossed_below:
            ticket = self.MarketOrder(
                self.spy,
                -self.spy_lot_shares,
                tag="Strategy A: close crossed below SMA(100)"
            )
            if self._order_was_accepted(ticket):
                self.spy_lot_shares = 0

        if (
            self.aapl_lot_shares > 0
            and self.aapl_rsi.Current.Value > Decimal("60")
        ):
            ticket = self.MarketOrder(
                self.aapl,
                -self.aapl_lot_shares,
                tag="Strategy B: RSI(14) above 60"
            )
            if self._order_was_accepted(ticket):
                self.aapl_lot_shares = 0

        if self.spy_lot_shares == 0 and self.spy_crossed_above:
            target_value = (
                Decimal("0.40") * self.Portfolio.TotalPortfolioValue
            )
            quantity = int(target_value / spy_bar.Close)

            if quantity > 0:
                ticket = self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A: close crossed above SMA(100)"
                )
                if self._order_was_accepted(ticket):
                    self.spy_lot_shares = quantity

        if self.aapl_lot_shares == 0 and self.aapl_red_streak >= 3:
            investment = Decimal("20000")

            if self.Portfolio.Cash >= investment:
                quantity = int(investment / aapl_bar.Close)

                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B: at least 3 consecutive red days"
                    )
                    if self._order_was_accepted(ticket):
                        self.aapl_lot_shares = quantity

    def _update_spy_state(self, bar):
        if self.last_spy_update == bar.EndTime:
            return

        self.last_spy_update = bar.EndTime
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        self.spy_sma.Update(bar.EndTime, bar.Close)

        if not self.spy_sma.IsReady:
            return

        current_sma = self.spy_sma.Current.Value

        if (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            self.spy_crossed_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and bar.Close > current_sma
            )
            self.spy_crossed_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and bar.Close < current_sma
            )

        self.previous_spy_close = bar.Close
        self.previous_spy_sma = current_sma

    def _update_aapl_state(self, bar):
        if self.last_aapl_update == bar.EndTime:
            return

        self.last_aapl_update = bar.EndTime

        if self.previous_aapl_close is not None:
            if bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.previous_aapl_close = bar.Close
        self.aapl_rsi.Update(bar.EndTime, bar.Close)

    def _reconcile_lots(self):
        if len(self.Transactions.GetOpenOrders(self.spy)) == 0:
            self.spy_lot_shares = max(
                0, int(self.Portfolio[self.spy].Quantity)
            )

        if len(self.Transactions.GetOpenOrders(self.aapl)) == 0:
            self.aapl_lot_shares = max(
                0, int(self.Portfolio[self.aapl].Quantity)
            )

    def _order_was_accepted(self, ticket):
        return (
            ticket is not None
            and ticket.Status != OrderStatus.Invalid
        )

