from AlgorithmImports import *
from decimal import Decimal


class StrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = SimpleMovingAverage(100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_rsi = RelativeStrengthIndex(
            14,
            MovingAverageType.Wilders
        )
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_samples = 0

        self.spy_lot_open = False
        self.aapl_lot_open = False

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars

        spy_crossed_above = False
        spy_crossed_below = False

        if bars.ContainsKey(self.spy):
            spy_bar = bars[self.spy]
            previous_close = self.spy_previous_close
            previous_sma = self.spy_previous_sma

            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            if (
                self.spy_sma.IsReady
                and previous_close is not None
                and previous_sma is not None
            ):
                current_sma = self.spy_sma.Current.Value
                spy_crossed_above = (
                    previous_close <= previous_sma
                    and spy_bar.Close > current_sma
                )
                spy_crossed_below = (
                    previous_close >= previous_sma
                    and spy_bar.Close < current_sma
                )

            self.spy_previous_close = spy_bar.Close
            self.spy_previous_sma = (
                self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            )

        if bars.ContainsKey(self.aapl):
            aapl_bar = bars[self.aapl]

            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_bar.Close
            self.aapl_samples += 1
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        self._synchronize_lots()

        if self.IsWarmingUp:
            return

        if not all(bars.ContainsKey(symbol) for symbol in self.all_symbols):
            return

        if not (
            self.spy_sma.IsReady
            and self.spy_previous_sma is not None
            and self.aapl_rsi.IsReady
            and self.aapl_samples >= 4
        ):
            return

        aapl_rsi_above_60 = (
            self.aapl_rsi.Current.Value > Decimal("60")
        )

        # Evaluate all sells before any buys.
        if self.spy_lot_open and spy_crossed_below:
            quantity = int(self.Portfolio[self.spy].Quantity)
            if quantity > 0:
                ticket = self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Strategy A sell"
                )
                if ticket.Status != OrderStatus.Invalid:
                    self.spy_lot_open = False

        if self.aapl_lot_open and aapl_rsi_above_60:
            quantity = int(self.Portfolio[self.aapl].Quantity)
            if quantity > 0:
                ticket = self.MarketOrder(
                    self.aapl,
                    -quantity,
                    tag="Strategy B sell"
                )
                if ticket.Status != OrderStatus.Invalid:
                    self.aapl_lot_open = False

        if not self.spy_lot_open and spy_crossed_above:
            quantity = int(self.CalculateOrderQuantity(self.spy, 0.40))
            if quantity > 0:
                ticket = self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A buy"
                )
                if ticket.Status != OrderStatus.Invalid:
                    self.spy_lot_open = True

        if not self.aapl_lot_open and self.aapl_red_streak >= 3:
            cash_required = Decimal("20000")
            if self.Portfolio.Cash >= cash_required:
                quantity = int(cash_required / bars[self.aapl].Close)
                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B buy"
                    )
                    if ticket.Status != OrderStatus.Invalid:
                        self.aapl_lot_open = True

    def _synchronize_lots(self):
        if len(self.Transactions.GetOpenOrders(self.spy)) == 0:
            self.spy_lot_open = self.Portfolio[self.spy].Quantity > 0

        if len(self.Transactions.GetOpenOrders(self.aapl)) == 0:
            self.aapl_lot_open = self.Portfolio[self.aapl].Quantity > 0

