            and not self._has_open_order(self.spy)
            and spy_crossed_below
        ):
            self.MarketOrder(
                self.spy, -spy_quantity, tag="Strategy A sell"
            )

        if (
            aapl_was_held
            and not self._has_open_order(self.aapl)
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(
                self.aapl, -aapl_quantity, tag="Strategy B sell"
            )

        if (
            not spy_was_held
            and not self._has_open_order(self.spy)
            and self.spy_sma.IsReady
            and spy_crossed_above
        ):
            self.SetHoldings(self.spy, 0.40, tag="Strategy A buy")

        if (
            not aapl_was_held
            and not self._has_open_order(self.aapl)
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = floor(20_000 / aapl_close)
            if quantity > 0:
                self.MarketOrder(
                    self.aapl, quantity, tag="Strategy B buy"
                )

    def _has_open_order(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

