from AlgorithmImports import *
from collections import deque
import math


class StrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_current_close = None
        self.spy_previous_sma = None
        self.spy_current_sma = None

        self.aapl_previous_close = None
        self.aapl_current_close = None
        self.aapl_red_streak = 0
        self.aapl_sample_count = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.last_spy_bar_time = None
        self.last_aapl_bar_time = None

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        has_spy = self._has_bar(data, self.spy)
        has_aapl = self._has_bar(data, self.aapl)

        if has_spy:
            spy_bar = data.Bars[self.spy]
            if self.last_spy_bar_time != spy_bar.EndTime:
                self._update_spy(spy_bar)
                self.last_spy_bar_time = spy_bar.EndTime

        if has_aapl:
            aapl_bar = data.Bars[self.aapl]
            if self.last_aapl_bar_time != aapl_bar.EndTime:
                self._update_aapl(aapl_bar)
                self.last_aapl_bar_time = aapl_bar.EndTime

        self._synchronize_lots()

        if self.IsWarmingUp:
            return

        if not all(self._has_bar(data, symbol) for symbol in self.symbols):
            return

        if not self._all_state_ready():
            return

        spy_crosses_above = (
            self.spy_previous_close <= self.spy_previous_sma
            and self.spy_current_close > self.spy_current_sma
        )
        spy_crosses_below = (
            self.spy_previous_close >= self.spy_previous_sma
            and self.spy_current_close < self.spy_current_sma
        )

        if self.strategy_a_lot > 0 and spy_crosses_below:
            quantity = self.strategy_a_lot
            self.MarketOrder(
                self.spy, -quantity, False, "Strategy A sell"
            )
            self.strategy_a_lot = 0

        if (
            self.strategy_b_lot > 0
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            quantity = self.strategy_b_lot
            self.MarketOrder(
                self.aapl, -quantity, False, "Strategy B sell"
            )
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = math.floor(target_value / self.spy_current_close)
            if quantity > 0:
                self.MarketOrder(
                    self.spy, quantity, False, "Strategy A buy"
                )
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000.0:
                quantity = math.floor(20_000.0 / self.aapl_current_close)
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl, quantity, False, "Strategy B buy"
                    )
                    self.strategy_b_lot = quantity

    def _has_bar(self, data, symbol):
        return (
            data.Bars.ContainsKey(symbol)
            and data.Bars[symbol] is not None
        )

    def _update_spy(self, bar):
        close = float(bar.Close)

        self.spy_previous_close = self.spy_current_close
        self.spy_previous_sma = self.spy_current_sma
        self.spy_current_close = close

        self.spy_closes.append(close)
        self.spy_current_sma = (
            sum(self.spy_closes) / 100.0
            if len(self.spy_closes) == 100
            else None
        )

    def _update_aapl(self, bar):
        close = float(bar.Close)

        if self.aapl_current_close is not None:
            if close < self.aapl_current_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_previous_close = self.aapl_current_close
        self.aapl_current_close = close
        self.aapl_sample_count += 1
        self.aapl_rsi.Update(bar.EndTime, bar.Close)

    def _all_state_ready(self):
        return (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_current_sma is not None
            and self.aapl_sample_count >= 4
            and self.aapl_rsi.IsReady
        )

    def _synchronize_lots(self):
        actual_spy_quantity = int(self.Portfolio[self.spy].Quantity)
        if self.strategy_a_lot > 0 and actual_spy_quantity > 0:
            self.strategy_a_lot = actual_spy_quantity

        actual_aapl_quantity = int(self.Portfolio[self.aapl].Quantity)
        if self.strategy_b_lot > 0 and actual_aapl_quantity > 0:
            self.strategy_b_lot = actual_aapl_quantity

