        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_samples = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14,
            MovingAverageType.Wilders
        )

        self.spy_lot = 0
        self.aapl_lot = 0

        # One extra sample is required so both today's and yesterday's
        # 100-day moving averages are fully formed for crossing tests.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        self._synchronize_lots()

        spy_crossed_above = False
        spy_crossed_below = False
        spy_cross_ready = False

        if data.Bars.ContainsKey(self.spy_symbol):
            (
                spy_crossed_above,
                spy_crossed_below,
                spy_cross_ready
            ) = self._update_spy_state(data.Bars[self.spy_symbol])

        if data.Bars.ContainsKey(self.aapl_symbol):
            self._update_aapl_state(data.Bars[self.aapl_symbol])

        for ticker in self.tickers:
            if not data.Bars.ContainsKey(self.symbols[ticker]):
                return

        if self.IsWarmingUp:
            return

        if not spy_cross_ready:
            return

        if not self.aapl_rsi.IsReady or self.aapl_samples < 4:
            return

        spy_close = Decimal(str(data.Bars[self.spy_symbol].Close))
        aapl_close = Decimal(str(data.Bars[self.aapl_symbol].Close))

        # Evaluate every sell before any buy.
        if self.spy_lot > 0 and spy_crossed_below:
            quantity = self.spy_lot
            ticket = self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Strategy A: close crossed below 100-day SMA"
            )
            if self._order_was_accepted(ticket):
                self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and Decimal(str(self.aapl_rsi.Current.Value)) > Decimal("60")
        ):
            quantity = self.aapl_lot
            ticket = self.MarketOrder(
                self.aapl_symbol,
                -quantity,
                tag="Strategy B: 14-day RSI above 60"
            )
            if self._order_was_accepted(ticket):
                self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            target_value = (
                Decimal(str(self.Portfolio.TotalPortfolioValue))
                * Decimal("0.40")
            )
            quantity = int(target_value / spy_close)

            if quantity > 0:
                ticket = self.MarketOrder(
                    self.spy_symbol,
                    quantity,
                    tag="Strategy A: close crossed above 100-day SMA"
                )
                if self._order_was_accepted(ticket):
                    self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            required_cash = Decimal("20000")
            available_cash = Decimal(str(self.Portfolio.Cash))

            if available_cash >= required_cash:
                quantity = int(required_cash / aapl_close)

                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.aapl_symbol,
                        quantity,
                        tag="Strategy B: AAPL red for at least 3 days"
                    )
                    if self._order_was_accepted(ticket):
                        self.aapl_lot = quantity

    def _update_spy_state(self, bar):
        close = Decimal(str(bar.Close))
        previous_close = self.spy_previous_close
        previous_sma = self.spy_previous_sma

        self.spy_closes.append(close)

        current_sma = None
        if len(self.spy_closes) == 100:
            current_sma = (
                sum(self.spy_closes, Decimal("0")) / Decimal("100")
            )

        ready = (
            previous_close is not None
            and previous_sma is not None
            and current_sma is not None
        )

        crossed_above = (
            ready
            and previous_close <= previous_sma
            and close > current_sma
        )
        crossed_below = (
            ready
            and previous_close >= previous_sma
            and close < current_sma
        )

        self.spy_previous_close = close
        self.spy_previous_sma = current_sma

        return crossed_above, crossed_below, ready

    def _update_aapl_state(self, bar):
        close = Decimal(str(bar.Close))

        if self.aapl_previous_close is None:
            self.aapl_red_streak = 0
        elif close < self.aapl_previous_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.aapl_previous_close = close
        self.aapl_samples += 1
        self.aapl_rsi.Update(bar.EndTime, bar.Close)

    def _synchronize_lots(self):
        if len(self.Transactions.GetOpenOrders(self.spy_symbol)) == 0:
            self.spy_lot = max(
                0,
                int(self.Portfolio[self.spy_symbol].Quantity)
            )

        if len(self.Transactions.GetOpenOrders(self.aapl_symbol)) == 0:
            self.aapl_lot = max(
                0,
                int(self.Portfolio[self.aapl_symbol].Quantity)
            )

    def _order_was_accepted(self, ticket):
        return (
            ticket is not None
            and ticket.Status not in (
                OrderStatus.Invalid,
                OrderStatus.Canceled
            )
        )

